"""Self-contained, read-only local dashboard for the loopback API."""

DASHBOARD_HTML = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Cyber Security Orchestrator</title>
<style>
:root{color-scheme:dark;--bg:#0b1020;--panel:#121a2d;--line:#283550;--text:#edf2ff;--muted:#a6b3ca;--accent:#79a8ff;--good:#72d6ad;--warn:#f2c879;--bad:#ff8f9b}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at top,#172443,var(--bg) 60%);color:var(--text);font:15px/1.5 system-ui,-apple-system,Segoe UI,sans-serif}main{max-width:1200px;margin:auto;padding:28px 18px 60px}header{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:24px}.brand{display:flex;gap:14px;align-items:center}.mark{width:44px;height:44px;border:1px solid #45659c;border-radius:13px;display:grid;place-items:center;color:var(--accent);font-weight:800;font-size:20px}.muted{color:var(--muted)}h1{font-size:clamp(22px,4vw,32px);margin:0}h2{font-size:18px;margin:0 0 12px}.panel{background:rgba(18,26,45,.94);border:1px solid var(--line);border-radius:16px;padding:18px;margin-bottom:16px;box-shadow:0 12px 35px #0002}.connect{display:flex;gap:10px;align-items:end;flex-wrap:wrap}.field{display:flex;flex-direction:column;gap:5px;min-width:180px;flex:1}label{font-size:12px;color:var(--muted)}input,select,button{font:inherit;border-radius:9px;border:1px solid #354663;padding:10px 12px;background:#0b1324;color:var(--text)}button{cursor:pointer;background:#20385e;border-color:#3c5e91;font-weight:650}button:hover{filter:brightness(1.15)}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--accent);outline-offset:2px}.status{font-size:13px;color:var(--muted);margin-top:10px}.status.error{color:var(--bad)}.status.ok{color:var(--good)}.cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.metric{padding:16px;border-radius:13px;background:#0d1628;border:1px solid var(--line)}.metric .value{font-size:27px;font-weight:750;letter-spacing:-.03em}.metric .label{font-size:12px;color:var(--muted)}nav{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px}.tab{background:#101a2d;color:var(--muted)}.tab[aria-selected=true]{background:#24416c;color:white;border-color:#5e8bd0}.toolbar{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:12px}.toolbar input{flex:1;min-width:180px}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:10px}table{width:100%;border-collapse:collapse;min-width:640px}th,td{text-align:left;padding:11px 12px;border-bottom:1px solid #26334b;vertical-align:top}th{font-size:12px;text-transform:uppercase;letter-spacing:.05em;color:var(--muted);background:#0e1729}tbody tr{cursor:pointer}tbody tr:hover{background:#1a2740}tbody tr:last-child td{border-bottom:0}.pill{display:inline-block;border-radius:999px;padding:2px 8px;background:#243451;font-size:12px}.pill.critical,.pill.high{color:var(--bad);background:#44212c}.pill.medium{color:var(--warn);background:#40351f}.empty{padding:28px;text-align:center;color:var(--muted)}details{margin-top:12px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#08101e;border:1px solid var(--line);padding:14px;border-radius:10px;max-height:360px;overflow:auto}.foot{font-size:12px;color:var(--muted);margin-top:20px}.hidden{display:none!important}@media(max-width:760px){.cards{grid-template-columns:repeat(2,minmax(0,1fr))}main{padding:18px 12px 40px}.panel{padding:13px}}@media(max-width:400px){.cards{grid-template-columns:1fr 1fr}.metric .value{font-size:22px}}
</style></head>
<body><main>
<header><div class="brand"><div class="mark">CS</div><div><h1>Cyber Security Orchestrator</h1><div class="muted">Local assessment dashboard · trends, comparisons, CSV export</div></div></div><span class="pill">API v1</span></header>
<section class="panel"><h2>Connect to local API</h2><div class="connect"><div class="field"><label for="token">Bearer token</label><input id="token" type="password" autocomplete="off" placeholder="Paste local API token"></div><button id="connect">Connect</button><button id="disconnect" class="tab">Disconnect</button></div><div id="status" class="status" role="status" aria-live="polite">Token stays in this page's memory and is not saved to browser storage.</div></section>
<section class="cards" aria-label="Overview metrics"><div class="metric"><div class="value" id="m-targets">—</div><div class="label">Registered targets</div></div><div class="metric"><div class="value" id="m-jobs">—</div><div class="label">Jobs in history</div></div><div class="metric"><div class="value" id="m-findings">—</div><div class="label">Findings</div></div><div class="metric"><div class="value" id="m-queue">—</div><div class="label">Pending notifications</div></div></section>
<section class="panel" style="margin-top:16px"><nav aria-label="Dashboard sections"><button class="tab" data-tab="targets" aria-selected="true">Targets</button><button class="tab" data-tab="jobs" aria-selected="false">Jobs</button><button class="tab" data-tab="findings" aria-selected="false">Findings</button><button class="tab" data-tab="comparisons" aria-selected="false">Comparisons</button><button class="tab" data-tab="risk" aria-selected="false">Risk</button><button class="tab" data-tab="contextual" aria-selected="false">Contextual Risk</button><button class="tab" data-tab="remediation" aria-selected="false">Remediation</button></nav>
<div class="toolbar"><input id="search" type="search" placeholder="Filter visible rows…" aria-label="Filter visible rows"><select id="filter" aria-label="Filter by status or severity"><option value="">All statuses / severities</option></select><button id="refresh">Refresh</button><button id="compare-jobs" class="hidden">Compare 2 selected jobs</button><button id="export">Export CSV</button><button id="portfolio-export" class="hidden">Export portfolio JSON</button><input id="metrics-start" type="date" class="hidden" aria-label="Metrics start date"><input id="metrics-end" type="date" class="hidden" aria-label="Metrics end date"><button id="metrics-json" class="hidden">Remediation metrics JSON</button><button id="metrics-csv" class="hidden">Remediation metrics CSV</button><button id="trend-compare" class="hidden">Compare periods</button><button id="trend-snapshot" class="hidden">Save trend snapshot</button><button id="risk-intelligence">Refresh risk intelligence</button></div><section id="risk-intelligence-panel" class="metric hidden" style="margin-bottom:14px"><h2>Risk intelligence rules &amp; alerts</h2><div class="toolbar"><label>Window days <input id="ri-window" type="number" min="1" max="90" value="7" style="width:100px"></label><label>Minimum findings <input id="ri-minimum" type="number" min="1" max="10000" value="3" style="width:120px"></label><label>Growth ratio <input id="ri-ratio" type="number" min="1" max="100" step="0.1" value="1.5" style="width:110px"></label><label><input id="ri-boost" type="checkbox" checked> Criticality boost</label><button id="ri-save">Save rules</button><button id="ri-preview">Preview rules (no save)</button></div><div class="toolbar"><select id="ri-type" aria-label="Filter alert type"><option value="">All types</option><option value="target_finding_growth">Finding growth</option><option value="recurring_finding">Recurring finding</option><option value="sla_backlog">SLA backlog</option></select><select id="ri-severity" aria-label="Filter alert severity"><option value="">All severities</option><option value="critical">Critical</option><option value="high">High</option><option value="warning">Warning</option><option value="info">Info</option></select><select id="ri-priority" aria-label="Filter alert priority"><option value="">All priorities</option><option value="P1">P1</option><option value="P2">P2</option><option value="P3">P3</option><option value="P4">P4</option></select><button id="ri-filter">Apply alert filters</button></div><div id="risk-intelligence-result" class="status">Refresh to analyze saved findings and remediation metadata.</div></section><section id="risk-rule-management-panel" class="metric hidden" style="margin-bottom:14px"><h2>Named risk rule sets &amp; audit</h2><div class="toolbar"><label>Rule name <input id="ri-named-name" maxlength="120" placeholder="e.g. Production strict" style="width:190px"></label><label>Description <input id="ri-named-description" maxlength="1000" placeholder="Optional purpose" style="width:220px"></label><label>Analyst <input id="ri-named-actor" maxlength="120" value="analyst" style="width:120px"></label><button id="ri-named-create">Save current settings as named rule</button><button id="ri-named-refresh">Refresh rules &amp; audit</button></div><div class="toolbar"><label>Compare rule IDs (2–10, comma-separated) <input id="ri-named-compare-ids" placeholder="1,2" style="width:150px"></label><button id="ri-named-compare">Compare rule sets</button><button id="ri-comparison-history">Comparison history</button></div><div id="ri-named-result" class="status">Named rule sets are independently stored. Comparisons are previews only.</div></section><section id="remediation-trends-panel" class="metric hidden" style="margin-bottom:14px"><h2>Remediation trends &amp; period comparison</h2><div id="remediation-trends-result" class="status">Choose a period and click Compare periods.</div></section><section id="job-compare-panel" class="metric hidden" style="margin-bottom:14px"><h2>Selected job comparison</h2><div id="job-compare-result"></div></section><section id="trend-panel" class="metric" style="margin-bottom:14px"><h2>Finding severity distribution</h2><div id="trend-bars" aria-label="Finding severity distribution"></div><div class="status">Distribution of findings currently loaded from the API (up to 500 records).</div></section>
<div class="table-wrap"><table><thead id="head"></thead><tbody id="body"><tr><td class="empty">Connect to load data.</td></tr></tbody></table></div><div class="status" id="count">No data loaded.</div>
<details id="detail-box" class="hidden"><summary>Selected record details</summary><div class="toolbar"><button id="target-report" class="hidden">Load target report</button><button id="download-report" class="hidden">Export target report JSON</button><select id="criticality-value" aria-label="Target business criticality"><option value="low">Low criticality</option><option value="medium" selected>Medium criticality</option><option value="high">High criticality</option><option value="critical">Critical business target</option></select><button id="save-criticality" class="hidden">Save target criticality</button></div><pre id="detail"></pre><div id="target-report-view" class="hidden"></div><section id="remediation-editor" class="hidden"><h3>Remediation plan</h3><p id="sla-guidance" class="muted">SLA is calculated from task creation date using the policy for the finding severity.</p><div class="toolbar"><select id="remediation-status" aria-label="Remediation status"><option value="open">Open</option><option value="in_progress">In progress</option><option value="blocked">Blocked</option><option value="resolved">Resolved</option><option value="accepted">Accepted risk</option></select><input id="remediation-assignee" maxlength="120" placeholder="Assignee" aria-label="Assignee"><input id="remediation-due" type="date" aria-label="Due date"></div><div class="toolbar"><input id="remediation-notes" maxlength="2000" placeholder="Notes / next action (max 2000 characters)" aria-label="Remediation notes"><button id="save-remediation">Save remediation</button></div><h4>Verification evidence</h4><p id="verification-state" class="muted">Unverified — successful verification is required before resolving a task.</p><div class="toolbar"><select id="verification-outcome" aria-label="Verification outcome"><option value="verified">Verified</option><option value="rejected">Rejected</option><option value="pending">Pending</option></select><input id="verification-by" maxlength="120" placeholder="Verified by" aria-label="Verified by"></div><div class="toolbar"><input id="verification-evidence" maxlength="2000" placeholder="Evidence reference or summary (max 2000 characters)" aria-label="Verification evidence"><input id="verification-notes" maxlength="2000" placeholder="Verification notes" aria-label="Verification notes"><button id="save-verification">Record verification</button></div></section></details></section>
<p class="foot">This dashboard only reads metadata through the loopback API. It does not execute scanners or send notifications. Use only targets you are authorized to assess.</p>
</main>
<script>
(() => {
'use strict';
let token = ''; let active = 'targets'; let records = []; let totals = {}; let selectedJobs = new Set(); let loadedTargetReport = null; let allFindings = []; let selectedFindingId = null; let remediationTasks = [];
const $ = id => document.getElementById(id);
const config = {
 targets:{path:'/api/v1/targets',columns:[['id','ID'],['url','Target URL'],['authorized','Authorized'],['criticality','Criticality'],['created_at','Created']],filter:null},
 jobs:{path:'/api/v1/jobs',columns:[['id','ID'],['target_id','Target ID'],['target_url','Target URL'],['tool','Tool'],['status','Status'],['created_at','Created']],filter:['queued','running','completed','failed','cancelled']},
 findings:{path:'/api/v1/findings',columns:[['id','ID'],['severity','Severity'],['title','Finding'],['source_tool','Source'],['target_url','Target'],['created_at','Created']],filter:['Critical','High','Medium','Low','Info']},
 comparisons:{path:'/api/v1/comparisons',columns:[['id','ID'],['before_job_id','Before job'],['after_job_id','After job'],['created_at','Compared at'],['summary','Summary']],filter:null},
 risk:{path:'/api/v1/risk/summary',columns:[['risk_priority','Priority'],['risk_score','Risk score'],['severity','Severity'],['title','Finding'],['target_url','Target'],['risk_taxonomy','Category']],filter:['P1','P2','P3','P4']},
 contextual:{path:'/api/v1/risk/contextual',columns:[['contextual_priority','Priority'],['contextual_risk_score','Contextual score'],['base_risk_score','Base score'],['target_criticality','Target criticality'],['repeatability_count','Repeatability'],['finding_age_days','Age (days)'],['title','Finding'],['target_url','Target']],filter:['P1','P2','P3','P4']},
 remediation:{path:'/api/v1/remediation',columns:[['id','Task ID'],['status','Status'],['severity','Severity'],['finding_title','Finding'],['target_url','Target'],['assignee','Assignee'],['due_date','Due date'],['sla_due_date','SLA due'],['sla_remaining_days','SLA days left'],['sla_status','SLA status'],['verification_status','Verification'],['updated_at','Updated']],filter:['open','in_progress','blocked','resolved','accepted']}
};
function status(message,kind=''){ $('status').textContent=message; $('status').className='status '+kind; }
function node(tag,text,cls){const el=document.createElement(tag); if(text!==undefined)el.textContent=String(text??'—'); if(cls)el.className=cls; return el;}
async function api(path){const response=await fetch(path,{headers:{Authorization:'Bearer '+token,Accept:'application/json'},cache:'no-store'});const text=await response.text();let data;try{data=JSON.parse(text)}catch{throw new Error('API returned invalid JSON (HTTP '+response.status+')')}if(!response.ok)throw new Error((data.error||'API request failed')+' (HTTP '+response.status+')');return data;}
async function apiPost(path,body){const response=await fetch(path,{method:'POST',headers:{Authorization:'Bearer '+token,Accept:'application/json','Content-Type':'application/json'},body:JSON.stringify(body),cache:'no-store'});const text=await response.text();let data;try{data=JSON.parse(text)}catch{throw new Error('API returned invalid JSON (HTTP '+response.status+')')}if(!response.ok)throw new Error((data.error||'API request failed')+' (HTTP '+response.status+')');return data;}
function setMetric(id,value){$(id).textContent=Number.isFinite(Number(value))?String(value):'—';}
function setupFilter(){const select=$('filter');select.replaceChildren(node('option','All statuses / severities'));select.firstChild.value='';for(const value of(config[active].filter||[])){const opt=node('option',value);opt.value=value;select.append(opt)}select.classList.toggle('hidden',!config[active].filter);}
function render(){const spec=config[active];$('trend-panel').classList.toggle('hidden',active!=='findings');$('portfolio-export').classList.toggle('hidden',active!=='risk');$('metrics-start').classList.toggle('hidden',active!=='remediation');$('metrics-end').classList.toggle('hidden',active!=='remediation');$('metrics-json').classList.toggle('hidden',active!=='remediation');$('metrics-csv').classList.toggle('hidden',active!=='remediation');$('trend-compare').classList.toggle('hidden',active!=='remediation');$('trend-snapshot').classList.toggle('hidden',active!=='remediation');$('compare-jobs').classList.toggle('hidden',active!=='jobs');$('compare-jobs').disabled=selectedJobs.size!==2;$('export').disabled=!records.length;$('head').replaceChildren();const tr=node('tr');if(active==='jobs')tr.append(node('th','Select'));for(const [,label] of spec.columns)tr.append(node('th',label));$('head').append(tr);const q=$('search').value.trim().toLowerCase(), f=$('filter').value;const visible=records.filter(row=>{const match=JSON.stringify(row).toLowerCase().includes(q);const field=active==='jobs'||active==='remediation'?'status':active==='findings'?'severity':active==='risk'?'risk_priority':active==='contextual'?'contextual_priority':null;return match&&(!f||(field&&String(row[field]||'').toLowerCase()===f.toLowerCase()))});const body=$('body');body.replaceChildren();if(!visible.length){const tr=node('tr');const td=node('td',undefined,'empty');td.textContent=records.length?'No records match these filters.':'No records found.';td.colSpan=spec.columns.length+(active==='jobs'?1:0);tr.append(td);body.append(tr)}else for(const row of visible){const tr=node('tr');tr.tabIndex=0;tr.setAttribute('aria-label','Show details for record '+(row.id??''));const selectRow=()=>{ $('detail').textContent=JSON.stringify(row,null,2);$('detail-box').classList.remove('hidden');$('target-report').classList.toggle('hidden',active!=='targets');$('save-criticality').classList.toggle('hidden',active!=='targets');$('criticality-value').classList.toggle('hidden',active!=='targets');if(active==='targets')$('criticality-value').value=row.criticality||'medium';$('download-report').classList.add('hidden');$('target-report-view').classList.add('hidden');loadedTargetReport=null;$('target-report').dataset.targetId=String(row.id??'');selectedFindingId=active==='findings'?Number(row.id):active==='remediation'?Number(row.finding_id):null;$('remediation-editor').classList.toggle('hidden',!selectedFindingId);const task=active==='remediation'?row:remediationTasks.find(t=>Number(t.finding_id)===selectedFindingId);if(selectedFindingId){$('remediation-status').value=task?.status||'open';$('remediation-assignee').value=task?.assignee||'';$('remediation-due').value=task?.due_date||'';$('remediation-notes').value=task?.notes||'';$('sla-guidance').textContent='SLA: '+(row.sla_status||task?.sla_status||'not available')+' · deadline '+(row.sla_due_date||task?.sla_due_date||'—')+' · '+(row.sla_days||task?.sla_days||'—')+' days for this severity.';$('verification-state').textContent='Latest verification: '+(row.verification_status||task?.verification_status||'unverified')+'. A successful verification is required before resolving.';}};tr.addEventListener('click',selectRow);tr.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectRow()}});if(active==='jobs'){const td=node('td');const check=document.createElement('input');check.type='checkbox';check.setAttribute('aria-label','Select job '+row.id);check.checked=selectedJobs.has(Number(row.id));check.addEventListener('click',e=>e.stopPropagation());check.addEventListener('change',()=>{if(check.checked){if(selectedJobs.size>=2){check.checked=false;status('Select exactly two jobs.','error');return}selectedJobs.add(Number(row.id))}else selectedJobs.delete(Number(row.id));$('compare-jobs').disabled=selectedJobs.size!==2});td.append(check);tr.append(td)}for(const [key] of spec.columns){const value=row[key];const td=node('td');if(key==='severity'||key==='status'){td.append(node('span',value,'pill '+String(value||'').toLowerCase()))}else if(key==='summary'&&value&&typeof value==='object'){td.textContent=Object.entries(value).map(([k,v])=>k+': '+v).join(' · ')}else td.textContent=key==='authorized'?(value?'Yes':'No'):(value??'—');tr.append(td)}body.append(tr)}$('count').textContent=`Showing ${visible.length} of ${records.length} loaded ${active}. Click a row to inspect details.`;if(active==='findings')renderTrends(records);if(active==='contextual'){const first=visible[0];if(first&&first.risk_reasons){$('trend-panel').classList.remove('hidden');$('trend-bars').replaceChildren(node('p','Contextual score combines base score, analyst-set target criticality, stored repeatability, data age and latest recorded assessment status. Select a row to inspect risk_reasons.'));}}}
function renderTrends(rows){const levels=['Critical','High','Medium','Low','Info','Unknown'];const counts=Object.fromEntries(levels.map(x=>[x,0]));for(const row of rows){const level=levels.includes(row.severity)?row.severity:'Unknown';counts[level]++;}const root=$('trend-bars');root.replaceChildren();const max=Math.max(1,...Object.values(counts));for(const level of levels){const line=node('div');line.style.cssText='display:grid;grid-template-columns:90px 1fr 40px;gap:10px;align-items:center;margin:7px 0';line.append(node('span',level));const track=node('div');track.style.cssText='height:12px;background:#0b1324;border-radius:8px;overflow:hidden';const bar=node('div');bar.style.cssText='height:100%;width:'+(counts[level]/max*100)+'%;background:'+(level==='Critical'||level==='High'?'#ff8f9b':level==='Medium'?'#f2c879':'#79a8ff');track.append(bar);line.append(track,node('strong',counts[level]));root.append(line);}}
function exportCSV(){const spec=config[active];const q=$('search').value.trim().toLowerCase(),f=$('filter').value;const visible=records.filter(row=>{const match=JSON.stringify(row).toLowerCase().includes(q);const field=active==='jobs'||active==='remediation'?'status':active==='findings'?'severity':active==='risk'?'risk_priority':active==='contextual'?'contextual_priority':null;return match&&(!f||(field&&String(row[field]||'').toLowerCase()===f.toLowerCase()));});const quote=value=>'"'+String(value??'').replace(/"/g,'""')+'"';const csv=[spec.columns.map(([,label])=>quote(label)).join(','),...visible.map(row=>spec.columns.map(([key])=>quote(typeof row[key]==='object'?JSON.stringify(row[key]):row[key])).join(','))].join('\r\n');const blob=new Blob(['\ufeff',csv],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=node('a');a.href=url;a.download='cybersec-'+active+'.csv';a.click();URL.revokeObjectURL(url);}
async function loadTargetReport(){const id=$('target-report').dataset.targetId;if(!id)return;try{loadedTargetReport=await api('/api/v1/targets/'+encodeURIComponent(id)+'/report');$('detail').textContent=JSON.stringify(loadedTargetReport.target,null,2);const view=$('target-report-view');view.replaceChildren();view.classList.remove('hidden');const h=node('h3','Target report');view.append(h);const summary=loadedTargetReport.summary;view.append(node('p',`Jobs: ${summary.job_count} · Findings: ${summary.finding_count}`));const severity=node('p',Object.entries(summary.severity).map(([k,v])=>k+': '+v).join(' · '));view.append(severity);view.append(node('h4','Daily finding trend'));if(!loadedTargetReport.daily_trend.length)view.append(node('p','No findings recorded for this target.'));else for(const day of loadedTargetReport.daily_trend)view.append(node('p',day.date+': '+day.total+' findings'));view.append(node('h4','Related jobs'));for(const job of loadedTargetReport.jobs)view.append(node('p','#'+job.id+' · '+job.tool+' · '+job.status+' · '+job.created_at));view.append(node('h4','Related findings'));for(const finding of loadedTargetReport.findings)view.append(node('p',finding.severity+' · '+finding.title+' · '+finding.created_at));$('download-report').classList.remove('hidden');status('Target report loaded.','ok')}catch(e){status(e.message,'error')}}
function compareSelectedJobs(){
if(selectedJobs.size!==2){status('Select exactly two jobs to compare.','error');return}
const ids=[...selectedJobs];const levels=['Critical','High','Medium','Low','Info'];
const counts=id=>Object.fromEntries(levels.map(level=>[level,allFindings.filter(f=>Number(f.job_id)===id&&f.severity===level).length]));
const left=counts(ids[0]),right=counts(ids[1]);const result=$('job-compare-result');result.replaceChildren();
result.append(node('p','Job #'+ids[0]+' vs Job #'+ids[1]+' · counts are based on currently loaded findings (up to 500).'));
for(const level of levels){const delta=right[level]-left[level];result.append(node('p',level+': '+left[level]+' → '+right[level]+' ('+(delta>0?'+':'')+delta+')'))}
$('job-compare-panel').classList.remove('hidden');status('Comparison calculated from stored findings; no scans were started.','ok')}
async function downloadPortfolioReport(){try{const report=await api('/api/v1/portfolio/report?limit=5000');const blob=new Blob([JSON.stringify(report,null,2)],{type:'application/json;charset=utf-8'});const url=URL.createObjectURL(blob);const a=node('a');a.href=url;a.download='cybersec-risk-portfolio.json';a.click();URL.revokeObjectURL(url);status('Portfolio report exported.','ok')}catch(e){status(e.message,'error')}}
function downloadTargetReport(){if(!loadedTargetReport)return;const blob=new Blob([JSON.stringify(loadedTargetReport,null,2)],{type:'application/json;charset=utf-8'});const url=URL.createObjectURL(blob);const a=node('a');a.href=url;a.download='cybersec-target-'+loadedTargetReport.target.id+'-report.json';a.click();URL.revokeObjectURL(url)}
async function downloadRemediationMetrics(format){if(!token){status('Connect before exporting remediation metrics.','error');return}const params=new URLSearchParams();if($('metrics-start').value)params.set('start_date',$('metrics-start').value);if($('metrics-end').value)params.set('end_date',$('metrics-end').value);const suffix=format==='csv'?'.csv':'';const path='/api/v1/remediation/metrics'+suffix+(params.size?'?'+params.toString():'');try{const response=await fetch(path,{headers:{Authorization:'Bearer '+token,Accept:format==='csv'?'text/csv':'application/json'},cache:'no-store'});const text=await response.text();if(!response.ok){let error;try{error=JSON.parse(text)}catch{}throw new Error((error?.error||'Metrics export failed')+' (HTTP '+response.status+')')}const blob=new Blob([text],{type:format==='csv'?'text/csv;charset=utf-8':'application/json;charset=utf-8'});const url=URL.createObjectURL(blob);const a=node('a');a.href=url;a.download='cybersec-remediation-metrics'+(format==='csv'?'.csv':'.json');a.click();URL.revokeObjectURL(url);status('Remediation metrics exported ('+(format.toUpperCase())+').','ok')}catch(e){status(e.message,'error')}}
async function load(){if(!token){status('Enter the API token and connect.');return}status('Loading dashboard…');try{const [targets,jobs,findings,queue,comparisons,risk,contextual,remediation]=await Promise.all([api('/api/v1/targets?limit=500'),api('/api/v1/jobs?limit=500'),api('/api/v1/findings?limit=500'),api('/api/v1/queue'),api('/api/v1/comparisons?limit=500'),api('/api/v1/risk/summary?limit=1000'),api('/api/v1/risk/contextual?limit=1000'),api('/api/v1/remediation?limit=500')]);totals={targets:targets.total,jobs:jobs.total,findings:findings.total};setMetric('m-targets',targets.total);setMetric('m-jobs',jobs.total);setMetric('m-findings',findings.total);const pending=queue.due_pending??queue.pending??queue.pending_count??'—';setMetric('m-queue',pending);allFindings=findings.items||[];remediationTasks=remediation.items||[];records=active==='risk'?(risk.top_risks||[]):active==='contextual'?(contextual.top_risks||[]):active==='remediation'?remediationTasks:(active==='targets'?targets:active==='jobs'?jobs:active==='findings'?findings:comparisons).items||[];render();status('Connected. Data refreshed from the local API.','ok')}catch(e){status(e.message,'error')}}
async function loadRemediationTrends(saveSnapshot=false){if(!token){status('Connect before viewing remediation trends.','error');return}const params=new URLSearchParams();if($('metrics-start').value)params.set('start_date',$('metrics-start').value);if($('metrics-end').value)params.set('end_date',$('metrics-end').value);try{const response=await fetch('/api/v1/remediation/trends'+(params.size?'?'+params.toString():''),{headers:{Authorization:'Bearer '+token,Accept:'application/json'},cache:'no-store'});const data=await response.json();if(!response.ok)throw new Error(data.error||'Trend request failed');$('remediation-trends-panel').classList.remove('hidden');const keys=[['tasks_created','Tasks created'],['resolved_in_period','Resolved'],['average_resolution_days','Average resolution days'],['sla_compliance_percent','SLA compliance %'],['verified_task_percent','Verified tasks %']];const table=document.createElement('table');const head=document.createElement('tr');['Metric','Current','Previous','Change','Change %'].forEach(v=>head.append(node('th',v)));table.append(head);for(const [key,label] of keys){const d=data.comparison[key]||{};const tr=document.createElement('tr');[label,d.current??'—',d.previous??'—',d.absolute_change??'—',d.percent_change===null||d.percent_change===undefined?'—':d.percent_change+'%'].forEach(v=>tr.append(node('td',String(v))));table.append(tr)}const daily=document.createElement('details');const summary=node('summary','Daily created / resolved counts');const pre=document.createElement('pre');pre.textContent=JSON.stringify(data.daily,null,2);daily.append(summary,pre);const container=$('remediation-trends-result');container.replaceChildren(node('p',`Period ${data.period.start_date} → ${data.period.end_date}; previous ${data.previous_period.start_date} → ${data.previous_period.end_date}. Open tasks by status: `+JSON.stringify(data.current_open_tasks_by_status)),table,daily);if(saveSnapshot){const saved=await apiPost('/api/v1/remediation/trend-snapshots',{start_date:data.period.start_date,end_date:data.period.end_date});status('Trend snapshot #'+saved.id+' saved.','ok')}else status('Period trends loaded.','ok')}catch(e){status(e.message,'error')}}
$('trend-compare').addEventListener('click',()=>loadRemediationTrends(false));$('trend-snapshot').addEventListener('click',()=>loadRemediationTrends(true));
async function loadRiskConfig(){const c=await api('/api/v1/risk/config');$('ri-window').value=c.window_days;$('ri-minimum').value=c.minimum_findings;$('ri-ratio').value=c.growth_ratio;$('ri-boost').checked=c.criticality_boost}
function riskRulePayload(){return {window_days:Number($('ri-window').value),minimum_findings:Number($('ri-minimum').value),growth_ratio:Number($('ri-ratio').value),criticality_boost:$('ri-boost').checked}}
async function loadRiskIntelligence(preview=false){if(!token){status('Connect before refreshing risk intelligence.','error');return}try{const params=new URLSearchParams();if(preview){for(const [k,v] of Object.entries(riskRulePayload()))params.set(k,String(v))}else{for(const [k,id] of [['alert_type','ri-type'],['severity','ri-severity'],['priority','ri-priority']])if($(id).value)params.set(k,$(id).value)}const path=preview?'/api/v1/risk/intelligence/preview':'/api/v1/risk/intelligence';const response=await fetch(path+(params.size?'?'+params.toString():''),{headers:{Authorization:'Bearer '+token,Accept:'application/json'},cache:'no-store'});const data=await response.json();if(!response.ok)throw new Error(data.error||'Risk intelligence request failed');$('risk-intelligence-panel').classList.remove('hidden');const container=$('risk-intelligence-result');container.replaceChildren();if(!data.items||!data.items.length){container.append(node('p',preview?'No signals match these rule settings.':'No alerts match the selected filters.'));status(preview?'Rule preview complete.':'Risk alerts refreshed.','ok');return}if(preview)container.append(node('p','PREVIEW ONLY — not saved. '+data.total+' signals from stored data.'));for(const alert of data.items){const card=document.createElement('article');card.className='metric';card.style.margin='8px 0';card.append(node('h3',alert.title+' · '+alert.severity.toUpperCase()+' · '+(alert.details?.priority||'P4')));card.append(node('p',alert.explanation));card.append(node('p','Status: '+alert.status+' · First seen: '+(alert.first_seen||'preview')+' · Last seen: '+(alert.last_seen||'preview')));const details=document.createElement('pre');details.textContent=JSON.stringify(alert.details,null,2);card.append(details);if(!preview&&alert.status==='open'){const button=node('button','Acknowledge alert');button.addEventListener('click',async()=>{const who=window.prompt('Analyst identifier','analyst');if(!who)return;try{await apiPost('/api/v1/risk/alerts/'+encodeURIComponent(alert.id)+'/acknowledge',{acknowledged_by:who});status('Alert acknowledged.','ok');await loadRiskIntelligence()}catch(e){status(e.message,'error')}});card.append(button)}container.append(card)}status(preview?'Rule preview complete; no alert rows were written.':'Risk intelligence refreshed from stored data.','ok')}catch(e){status(e.message,'error')}}
$('risk-intelligence').addEventListener('click',async()=>{try{await loadRiskConfig();await loadRiskIntelligence()}catch(e){status(e.message,'error')}});
$('ri-save').addEventListener('click',async()=>{try{const data=await apiPost('/api/v1/risk/config',riskRulePayload());status('Risk rules saved.','ok');await loadRiskIntelligence()}catch(e){status(e.message,'error')}});
$('ri-preview').addEventListener('click',()=>loadRiskIntelligence(true));$('ri-filter').addEventListener('click',()=>loadRiskIntelligence(false));
async function loadNamedRiskRules(){const data=await api('/api/v1/risk/rules?audit=true');$('risk-rule-management-panel').classList.remove('hidden');const box=$('ri-named-result');box.replaceChildren();box.append(node('p',data.total+' named rules. Audit entries shown: '+(data.audit||[]).length+'.'));for(const rule of data.items){const card=document.createElement('article');card.className='metric';card.style.margin='8px 0';card.append(node('h3','#'+rule.id+' · '+rule.name+' · '+(rule.enabled?'ENABLED':'DISABLED')));card.append(node('p',rule.description||'No description'));card.append(node('p','Updated by '+rule.updated_by+' · '+rule.updated_at));const pre=document.createElement('pre');pre.textContent=JSON.stringify(rule.config,null,2);card.append(pre);const toggle=node('button',rule.enabled?'Disable rule':'Enable rule');toggle.addEventListener('click',async()=>{try{await apiPost('/api/v1/risk/rules/'+rule.id+'/enabled',{enabled:!rule.enabled,actor:$('ri-named-actor').value||'analyst'});await loadNamedRiskRules();status('Named rule updated and audit logged.','ok')}catch(e){status(e.message,'error')}});card.append(toggle);const versions=node('button','View versions');versions.addEventListener('click',async()=>{try{const data=await api('/api/v1/risk/rules/'+rule.id+'/versions');const pre=document.createElement('pre');pre.textContent=JSON.stringify(data.items,null,2);card.append(pre)}catch(e){status(e.message,'error')}});card.append(versions);const rollback=node('button','Rollback version');rollback.addEventListener('click',async()=>{const raw=window.prompt('Version number to restore (a new version will be created)','1');if(raw===null)return;const version=Number(raw);if(!Number.isInteger(version)||version<1){status('Enter a positive version number.','error');return}try{await apiPost('/api/v1/risk/rules/'+rule.id+'/rollback',{version_number:version,actor:$('ri-named-actor').value||'analyst'});await loadNamedRiskRules();status('Rule rolled back as a new version.','ok')}catch(e){status(e.message,'error')}});card.append(rollback);box.append(card)}const audit=document.createElement('details');audit.append(node('summary','Recent rule audit history'));const pre=document.createElement('pre');pre.textContent=JSON.stringify(data.audit||[],null,2);audit.append(pre);box.append(audit)}
$('ri-named-create').addEventListener('click',async()=>{try{const name=$('ri-named-name').value.trim();const description=$('ri-named-description').value.trim();const actor=$('ri-named-actor').value.trim()||'analyst';const result=await apiPost('/api/v1/risk/rules',{name,description,actor,config:riskRulePayload()});$('ri-named-name').value='';status('Named rule #'+result.id+' saved.','ok');await loadNamedRiskRules()}catch(e){status(e.message,'error')}});
$('ri-named-refresh').addEventListener('click',async()=>{try{await loadNamedRiskRules()}catch(e){status(e.message,'error')}});
$('ri-named-compare').addEventListener('click',async()=>{try{const ids=$('ri-named-compare-ids').value.split(',').map(v=>v.trim()).filter(Boolean);if(ids.some(v=>!/^\d+$/.test(v)))throw new Error('Enter comma-separated numeric rule IDs.');const data=await api('/api/v1/risk/rules/compare?ids='+encodeURIComponent(ids.join(',')));const box=$('ri-named-result');box.replaceChildren(node('p',data.note));const table=document.createElement('table');const head=document.createElement('tr');['Rule','Enabled','Signals','P1','P2','P3','P4'].forEach(v=>head.append(node('th',v)));table.append(head);for(const item of data.results){const tr=document.createElement('tr');[item.name,String(item.enabled),item.total_signals,item.by_priority.P1,item.by_priority.P2,item.by_priority.P3,item.by_priority.P4].forEach(v=>tr.append(node('td',String(v))));table.append(tr)}box.append(table);for(const item of data.results){const details=document.createElement('details');details.append(node('summary',item.name+' signal details'));const pre=document.createElement('pre');pre.textContent=JSON.stringify(item.signals,null,2);details.append(pre);box.append(details)}status('Rule sets compared using stored metadata only.','ok')}catch(e){status(e.message,'error')}});
$('ri-comparison-history').addEventListener('click',async()=>{try{const data=await api('/api/v1/risk/comparison-history');const box=$('ri-named-result');box.replaceChildren(node('p',data.total+' saved comparison records.'));for(const item of data.items){const details=document.createElement('details');details.append(node('summary','#'+item.id+' · '+item.created_at+' · '+item.created_by));const pre=document.createElement('pre');pre.textContent=JSON.stringify(item.summary,null,2);details.append(pre);const open=node('button','Open full result');open.addEventListener('click',async()=>{try{const full=await api('/api/v1/risk/comparison-history/'+item.id);pre.textContent=JSON.stringify(full.result,null,2)}catch(e){status(e.message,'error')}});details.append(open);box.append(details)}status('Saved rule comparison history loaded.','ok')}catch(e){status(e.message,'error')}});
$('save-verification').addEventListener('click',async()=>{if(!selectedFindingId){status('Select a finding or remediation task first.','error');return}try{let task=remediationTasks.find(t=>Number(t.finding_id)===selectedFindingId);if(!task){task=await apiPost('/api/v1/findings/'+encodeURIComponent(selectedFindingId)+'/remediation',{status:$('remediation-status').value,assignee:$('remediation-assignee').value,due_date:$('remediation-due').value,notes:$('remediation-notes').value})}const result=await apiPost('/api/v1/remediation/'+encodeURIComponent(task.id)+'/verification',{outcome:$('verification-outcome').value,evidence:$('verification-evidence').value,notes:$('verification-notes').value,verified_by:$('verification-by').value});$('verification-state').textContent='Latest verification: '+result.outcome+' · '+(result.verified_by||'verifier not specified');status('Verification recorded.','ok');await load()}catch(e){status(e.message,'error')}});$('save-remediation').addEventListener('click',async()=>{if(!selectedFindingId)return;const due=$('remediation-due').value;try{await apiPost('/api/v1/findings/'+encodeURIComponent(selectedFindingId)+'/remediation',{status:$('remediation-status').value,assignee:$('remediation-assignee').value,due_date:due,notes:$('remediation-notes').value});status('Remediation task saved.','ok');await load();$('detail-box').classList.add('hidden')}catch(e){status(e.message,'error')}});$('save-criticality').addEventListener('click',async()=>{const id=$('target-report').dataset.targetId;if(!id)return;try{await apiPost('/api/v1/targets/'+encodeURIComponent(id)+'/criticality',{criticality:$('criticality-value').value});status('Target criticality saved. Refreshing contextual risk…','ok');await load()}catch(e){status(e.message,'error')}});$('portfolio-export').addEventListener('click',downloadPortfolioReport);$('metrics-json').addEventListener('click',()=>downloadRemediationMetrics('json'));$('metrics-csv').addEventListener('click',()=>downloadRemediationMetrics('csv'));$('compare-jobs').addEventListener('click',compareSelectedJobs);$('target-report').addEventListener('click',loadTargetReport);$('download-report').addEventListener('click',downloadTargetReport);$('connect').addEventListener('click',async()=>{token=$('token').value.trim();if(!token){status('Enter the API bearer token.','error');return}await load()});$('disconnect').addEventListener('click',()=>{token='';$('token').value='';records=[];$('portfolio-export').classList.add('hidden');['m-targets','m-jobs','m-findings','m-queue'].forEach(id=>$(id).textContent='—');$('body').replaceChildren();const tr=node('tr');const td=node('td','Connect to load data.','empty');td.colSpan=6;tr.append(td);$('body').append(tr);$('detail-box').classList.add('hidden');$('target-report-view').classList.add('hidden');$('remediation-editor').classList.add('hidden');loadedTargetReport=null;remediationTasks=[];selectedFindingId=null;selectedJobs.clear();allFindings=[];$('job-compare-panel').classList.add('hidden');$('trend-panel').classList.add('hidden');status('Disconnected. Token cleared from page memory.')});$('refresh').addEventListener('click',load);$('export').addEventListener('click',exportCSV);$('search').addEventListener('input',render);$('filter').addEventListener('change',render);document.querySelectorAll('[data-tab]').forEach(button=>button.addEventListener('click',()=>{active=button.dataset.tab;if(active!=='jobs')$('job-compare-panel').classList.add('hidden');document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-selected',String(b===button)));setupFilter();$('search').value='';$('detail-box').classList.add('hidden');if(token)load();else render()}));setupFilter();$('trend-panel').classList.add('hidden');
})();
</script></body></html>'''


